import urllib.parse


def normalize_segments(path):
    if not isinstance(path, str) or not path.startswith('/'):
        raise ValueError("path must be a string starting with '/'")

    raw_segments = path.split('/')
    segments = []
    for raw in raw_segments:
        if raw == '':
            continue

        out = bytearray()
        i = 0
        n = len(raw)
        while i < n:
            ch = raw[i]
            if ch == '%':
                if i + 2 >= n:
                    raise ValueError("invalid percent-encoding")
                h1 = raw[i + 1]
                h2 = raw[i + 2]
                if not (h1 in '0123456789abcdefABCDEF' and h2 in '0123456789abcdefABCDEF'):
                    raise ValueError("invalid percent-encoding")
                out.append(int(h1 + h2, 16))
                i += 3
            else:
                out.extend(ch.encode('utf-8'))
                i += 1

        try:
            decoded = out.decode('utf-8', errors='strict')
        except UnicodeDecodeError:
            raise ValueError("invalid UTF-8 after percent-decoding")

        if decoded == '.':
            continue
        elif decoded == '..':
            if not segments:
                raise ValueError("cannot pop from empty segment stack")
            segments.pop()
        else:
            segments.append(decoded)

    return tuple(segments)
